  if (abs(m - n) > 1) return false;
  if (m > n) {
    char *tmp = first;
    first = second;
    second = tmp;
    int t = m;
    m = n;
    n = t;
  }
  for (int i = 0; i < m; i++) {
    if (first[i] != second[i]) {
      if (m == n) return strcmp(first + i + 1, second + i + 1) == 0;
      return strcmp(first + i, second + i + 1) == 0;
    }
  }
  return true;
}

class Solution {
public:
  bool oneEditAway(string first, string second) {
    int m = first.size(), n = second.size();
    if (abs(m - n) > 1) return false;
    if (m > n) return oneEditAway(second, first);
    for (int i = 0; i < m; i++) {
      if (first[i] != second[i]) {
        if (m == n) return first.substr(i + 1) == second.substr(i + 1);
        return first.substr(i) == second.substr(i + 1);
      }
    }
    return true;
  }
};

